test('a genuinely new objective can dispatch its own identically worded suggestion',async t=>{const h=fixture(t),first=await h.brief({objective:'准备周一会议'}),item=first.items.find(x=>x.section==='nextSteps');await h.service.handoff(owner,{project:root,revision:first.revision,itemId:item.id,task:'整理周一会议资料',userRequested:true});const next=await h.brief({objective:'准备周五会议'}),newItem=next.items.find(x=>x.section==='nextSteps');const result=await h.service.handoff(owner,{project:root,revision:next.revision,itemId:newItem.id,task:'整理周五会议资料',userRequested:true});assert.equal(result.accepted,true);assert.equal(h.calls.coordinates.length,2);});
const deferred=()=>{let resolve;const promise=new Promise(r=>resolve=r);return{promise,resolve};};
function fixture(t,extra={}){
 assert.equal(typeof mod?.createContextLoop,'function');let state,scope={projectId:'p',projectRoot:root,label:'项目',bindingKey:'a'.repeat(64)},grant='b'.repeat(64),text='私信摘要资料。'.repeat(100)+'XSECRET',fetchedAt=at,failSource=null,jobStatus='running';const calls={reads:[],models:[],coordinates:[],writes:[]};
 const options={store:{get:async()=>state,put:async(_k,v)=>{state=structuredClone(v);calls.writes.push(state);}},readScope:async()=>scope,authorizeSync:()=>!!scope,authorization:async()=>grant,readQuery:async(_o,q)=>{calls.reads.push(q);if(q.source===failSource)throw Error('PRIVATE_PROVIDER');return{source:q.source,items:[{id:q.source+'1',title:'项目资料',text}],fetchedAt,truncated:false};},readProject:async()=>({project:{root},sources:['README.md','.agent/memory/context.md','.agent/memory/progress.md'].map(path=>({path,status:'ok',text:'项目公开说明',modifiedAt:fetchedAt,truncated:false}))}),readMemory:async()=>({goals:[],entries:[]}),summarize:async input=>{calls.models.push(input);return{changes:[{kind:'inference',text:'项目资料需要继续核对。',sourceIds:[(input.sources.find(s=>s.role==='file')??input.sources[0]).sourceId]}],blockers:[],nextSteps:[{kind:'suggestion',text:'建议核对本次进展。',sourceIds:[input.sources[0].sourceId]}]};},coordinate:async(_o,args,meta)=>{calls.coordinates.push({args,meta});return{status:'accepted',accepted:true,jobId:'job1'};},readJob:async()=>({jobs:[{id:'job1',status:jobStatus,reply:jobStatus==='completed'?'执行摘要，仍待验收。':'',delivery:{status:'reported_sent'}}]}),clock:()=>new Date(at),...extra};
 const service=mod.createContextLoop(options);t.after(()=>service.close());return{service,calls,restart:()=>{const next=mod.createContextLoop(options);t.after(()=>next.close());return next;},stored:()=>state,setScope:v=>scope=v,scope:()=>scope,setGrant:v=>grant=v,setText:v=>text=v,setFetched:v=>fetchedAt=v,setFailure:v=>failSource=v,setJob:v=>jobStatus=v,brief:args=>service.brief(owner,{project:root,objective:'推进项目上线',queries,userRequested:true,...args})};
}
