test('source-only state survives restart and cancellation cannot reactivate completed history',async t=>{
 let invalid=false;const h=fixture(t,{summarize:async()=>{if(invalid)throw Object.assign(Error('PRIVATE'),{code:'MODEL_INVALID_OUTPUT'});return{changes:[],blockers:[],nextSteps:[]};}});
 const complete=await h.brief();h.setText('new read');invalid=true;const partial=await h.brief();await h.service.close();const restarted=h.restart();await restarted.ready();
 const inspection=await restarted.inspect(owner,{project:root});assert.equal(inspection.loopId,partial.loopId);assert.equal(inspection.analysisState,'source_only');assert.equal(inspection.revision,complete.revision+1);assert.equal(inspection.summary,undefined);assert.equal(inspection.lastSuccessful,undefined);
 await assert.rejects(restarted.check(owner,{project:root,loopId:partial.loopId}),e=>e.code==='LOOP_MODEL_INVALID_OUTPUT');
 await restarted.cancel(owner,{project:root,userRequested:true});assert.deepEqual(h.stored().loops,[]);await assert.rejects(restarted.inspect(owner,{project:root}),e=>e.code==='LOOP_NOT_FOUND');
});

test('legacy complete rows load as complete while malformed source-only rows fail closed',async t=>{
 const h=fixture(t),first=await h.brief();await h.service.close();delete h.stored().loops[0].analysisState;const restarted=h.restart();await restarted.ready();const inspection=await restarted.inspect(owner,{project:root});assert.equal(inspection.analysisState,'complete');assert.equal(inspection.loopId,first.loopId);
 const snapshot=fixture(t,{summarize:async()=>{throw Object.assign(Error('PRIVATE'),{code:'MODEL_INVALID_OUTPUT'});}});await snapshot.brief();const good=structuredClone(snapshot.stored());assert.equal(mod.contextLoopRowSchema.safeParse(good).success,true);
 for(const mutation of [row=>row.summary={changes:[],blockers:[],nextSteps:[]},row=>row.modelDiagnostic='PRIVATE_PROVIDER_TEXT',row=>row.validationDiagnostic='PRIVATE_PROVIDER_TEXT',row=>row.items=[{kind:'suggestion',text:'unverified',sourceIds:['x'],id:'a'.repeat(64),number:1,section:'nextSteps'}],row=>row.lastSuccessful={...row}]){const invalid=structuredClone(good);mutation(invalid.loops[0]);assert.equal(mod.contextLoopRowSchema.safeParse(invalid).success,false);}
});

test('source-only commit failure restores completed history and fails closed',async t=>{
 let state,invalid=false,failSave=false;const h=fixture(t,{store:{get:async()=>state,put:async(_key,value)=>{state=structuredClone(value);if(failSave){failSave=false;throw Error('PRIVATE_STORE_FAILURE_AFTER_WRITE');}}},summarize:async()=>{if(invalid)throw Object.assign(Error('PRIVATE'),{code:'MODEL_INVALID_OUTPUT'});return{changes:[],blockers:[],nextSteps:[]};}});
 await h.brief();const before=structuredClone(state);h.setText('new snapshot');invalid=true;failSave=true;
 await assert.rejects(h.brief(),e=>e.code==='LOOP_STORE_UNAVAILABLE');assert.deepEqual(state,before);const reads=h.calls.reads.length;await assert.rejects(h.service.inspect(owner,{project:root}),e=>e.code==='LOOP_STORE_UNAVAILABLE');assert.equal(h.calls.reads.length,reads);
});

test('revocation during source-only save restores the entire previous active row',async t=>{
 let state,invalid=false,hold=false;const entered=deferred(),release=deferred(),h=fixture(t,{store:{get:async()=>state,put:async(_key,value)=>{if(hold){hold=false;entered.resolve();await release.promise;}state=structuredClone(value);}},summarize:async()=>{if(invalid)throw Object.assign(Error('PRIVATE'),{code:'MODEL_INVALID_OUTPUT'});return{changes:[],blockers:[],nextSteps:[]};}});
 await h.brief();const before=structuredClone(state);h.setText('new snapshot');invalid=true;hold=true;const pending=h.brief();await entered.promise;h.setGrant('e'.repeat(64));release.resolve();await assert.rejects(pending,e=>e.code==='LOOP_AUTH_CHANGED');await h.service.close();assert.deepEqual(state,before);
});

test('each model retry guard rejects a revoked scope before another model request',async t=>{
 let requests=0;const h=fixture(t,{summarize:async input=>{assert.equal(typeof input.beforeRequest,'function');await input.beforeRequest();requests++;h.setGrant('e'.repeat(64));await input.beforeRequest();requests++;return{changes:[],blockers:[],nextSteps:[]};}});
 await assert.rejects(h.brief(),e=>e.code==='LOOP_AUTH_CHANGED');assert.equal(requests,1);assert.equal(h.calls.writes.length,0);
});

test('source-only snapshots persist only fixed Google read diagnostics across error wrappers',async t=>{
 const h=fixture(t,{readQuery:async(_owner,q)=>{throw Object.assign(Error('PRIVATE_RESPONSE_BODY'),{code:'CONTEXT_PROTOCOL_INVALID',readStage:q.source==='gmail'?'projection':'PRIVATE_URL',readDiagnostic:q.source==='gmail'?{operation:'gmail_metadata',stage:'message_shape',reason:'message_invalid',body:'PRIVATE_RESPONSE_BODY'}:{operation:'PRIVATE_QUERY',stage:'PRIVATE_URL',reason:'PRIVATE_TOKEN'}});},summarize:async()=>{throw Object.assign(Error('PRIVATE_MODEL'),{code:'MODEL_INVALID_OUTPUT'});}});
 const partial=await h.brief();assert.deepEqual(partial.sourceDiagnostics,[{source:'gmail',code:'CONTEXT_PROTOCOL_INVALID',readStage:'projection',readDiagnostic:{operation:'gmail_metadata',stage:'message_shape',reason:'message_invalid'}},{source:'calendar',code:'CONTEXT_PROTOCOL_INVALID',readDiagnostic:{operation:'unknown',stage:'unknown',reason:'unknown'}}]);
 assert.deepEqual(h.stored().loops[0].sourceDiagnostics,partial.sourceDiagnostics);assert.doesNotMatch(JSON.stringify(h.stored()),/PRIVATE_RESPONSE|PRIVATE_URL|PRIVATE_QUERY|PRIVATE_TOKEN|PRIVATE_MODEL/);
 const invalid=structuredClone(h.stored());invalid.loops[0].sourceDiagnostics[0].readDiagnostic.body='PRIVATE_RESPONSE_BODY';assert.equal(mod.contextLoopRowSchema.safeParse(invalid).success,false);
});

test('source-only storage retains fixed HTTP shapes and rejects unbounded diagnostic fields',async t=>{
 const diagnostic={operation:'gmail_list',stage:'body_read',reason:'response_shape',responseStatus:204,bodyShape:'null',headersShape:'get',responseShape:'object'};
 const h=fixture(t,{readQuery:async()=>{throw Object.assign(Error('PRIVATE'),{code:'CONTEXT_PROTOCOL_INVALID',readStage:'call',readDiagnostic:{...diagnostic,url:'PRIVATE_URL',body:'PRIVATE_BODY',headerValue:'PRIVATE_HEADER'}});},summarize:async()=>{throw Object.assign(Error('PRIVATE'),{code:'MODEL_INVALID_OUTPUT'});}});
 const partial=await h.brief();assert.deepEqual(partial.sourceDiagnostics[0].readDiagnostic,diagnostic);assert.deepEqual(h.stored().loops[0].sourceDiagnostics[0].readDiagnostic,diagnostic);assert.doesNotMatch(JSON.stringify(h.stored()),/PRIVATE/);
 for(const patch of [{responseStatus:600},{responseStatus:200.1},{responseStatus:'200'},{bodyShape:'PRIVATE_BODY'},{headersShape:'PRIVATE_HEADER'},{responseShape:'PRIVATE_RESPONSE'},{body:'PRIVATE_BODY'}]){
  const row=structuredClone(h.stored());Object.assign(row.loops[0].sourceDiagnostics[0].readDiagnostic,patch);assert.equal(mod.contextLoopRowSchema.safeParse(row).success,false);
 }
 const row=structuredClone(h.stored());row.loops[0].sourceDiagnostics[0].readDiagnostic.responseStatus=null;assert.equal(mod.contextLoopRowSchema.safeParse(row).success,true);
});

test('source-only follow-up cannot stream after permission changes during model preparation',async t=>{
 let allowed=true,attempts=0,streams=0;const prepared=deferred(),release=deferred();
 const h=fixture(t,{authorizationSync:()=>allowed,summarize:async input=>{
  attempts++;await input.beforeRequest();
  if(attempts===1){streams++;throw Object.assign(Error('PRIVATE_MODEL'),{code:'MODEL_INVALID_OUTPUT'});}
  prepared.resolve();await release.promise;
  input.beforeRequestSync();streams++;
  return{changes:[],blockers:[],nextSteps:[]};
 }});
 const partial=await h.brief(),before=structuredClone(h.stored());assert.equal(partial.analysisState,'source_only');
 const checking=h.service.check(owner,{project:root,loopId:partial.loopId});await prepared.promise;allowed=false;release.resolve();
 await assert.rejects(checking,e=>e.code==='LOOP_AUTH_CHANGED');assert.equal(attempts,2);assert.equal(streams,1);assert.deepEqual(h.stored(),before);
});
